COMMENT ON COLUMN PLAYSTORE.APP IS 'Application name';
COMMENT ON COLUMN PLAYSTORE.CATEGORY IS 'Category the app belongs to';
ALTER TABLE PLAYSTORE MODIFY (CATEGORY ANNOTATIONS (ADD value_description 'FAMILY 18%GAME 11%Other (7725) 71%'));
COMMENT ON COLUMN PLAYSTORE.RATING IS 'Overall user rating of the app (as when scraped)';
COMMENT ON COLUMN PLAYSTORE.REVIEWS IS 'Number of user reviews for the app (as when scraped)';
COMMENT ON COLUMN PLAYSTORE."SIZE" IS 'Size of the app (as when scraped)';
ALTER TABLE PLAYSTORE MODIFY ("SIZE" ANNOTATIONS (ADD value_description 'Varies with device 16%11M 2%Other (8948) 83%'));
COMMENT ON COLUMN PLAYSTORE.INSTALLS IS 'Number of user downloads/installs for the app (as when scraped)';
ALTER TABLE PLAYSTORE MODIFY (INSTALLS ANNOTATIONS (ADD value_description '1,000,000+ 15%10,000,000+ 12%Other (8010) 74%'));
COMMENT ON COLUMN PLAYSTORE."TYPE" IS 'Paid or Free';
ALTER TABLE PLAYSTORE MODIFY ("TYPE" ANNOTATIONS (ADD value_description 'Only has ''Paid'' and ''Free''Free 93%Paid 7%'));
COMMENT ON COLUMN PLAYSTORE.PRICE IS 'Price of the app (as when scraped)';
ALTER TABLE PLAYSTORE MODIFY (PRICE ANNOTATIONS (ADD value_description '0 93%$0.99 1%Other (653) 6%commonsense evidence:Free means the price is 0.'));
COMMENT ON COLUMN PLAYSTORE."CONTENT RATING" IS 'Age group the app is targeted at - Children / Mature 21+ / Adult';
ALTER TABLE PLAYSTORE MODIFY ("CONTENT RATING" ANNOTATIONS (ADD value_description 'Everyone 80%Teen 11%Other (919) 8%commonsense evidence:According to Wikipedia, the different age groups are defined as:Children: age<12~13Teen: 13~19Adult/Mature: 21+'));
COMMENT ON COLUMN PLAYSTORE.GENRES IS 'An app can belong to multiple genres (apart from its main category).';
ALTER TABLE PLAYSTORE MODIFY (GENRES ANNOTATIONS (ADD value_description 'Tools 8%Entertainment 6%Other (9376) 86%'));
COMMENT ON COLUMN PLAYSTORE_USER_REVIEWS.APP IS 'Name of app';
COMMENT ON COLUMN PLAYSTORE_USER_REVIEWS.TRANSLATED_REVIEW IS 'User review (Preprocessed and translated to English)';
ALTER TABLE PLAYSTORE_USER_REVIEWS MODIFY (TRANSLATED_REVIEW ANNOTATIONS (ADD value_description 'nan 42%Good 0%Other (37185) 58%'));
COMMENT ON COLUMN PLAYSTORE_USER_REVIEWS.SENTIMENT IS 'Overall user rating of the app (as when scraped)';
ALTER TABLE PLAYSTORE_USER_REVIEWS MODIFY (SENTIMENT ANNOTATIONS (ADD value_description 'commonsense evidence:Positive: user holds positive attitude towards this appNegative: user holds positive attitude / critizes on this appNeural: user holds neural attitudenan: user doesn''t comment on this app.'));
COMMENT ON COLUMN PLAYSTORE_USER_REVIEWS.SENTIMENT_POLARITY IS 'Sentiment polarity score';
ALTER TABLE PLAYSTORE_USER_REVIEWS MODIFY (SENTIMENT_POLARITY ANNOTATIONS (ADD value_description 'commonsense evidence:• score >= 0.5 it means pretty positive or pretty like this app.• 0 <= score < 0.5: it means user mildly likes this app.• -0.5 <= score < 0: it means this user mildly dislikes this app or slightly negative attitude• score <-0.5: it means this user dislikes this app pretty much.'));
COMMENT ON COLUMN PLAYSTORE_USER_REVIEWS.SENTIMENT_SUBJECTIVITY IS 'Sentiment subjectivity score';
ALTER TABLE PLAYSTORE_USER_REVIEWS MODIFY (SENTIMENT_SUBJECTIVITY ANNOTATIONS (ADD value_description 'commonsense evidence:more subjectivity refers to less objectivity, vice versa.'));